def restore_native_channel_reader_successor_parent_source(source,relative):
    recipe=RESTORATIONS.get(relative)
    if recipe is None:return source
    digest=lambda text:sha256(ast.unparse(ast.parse(text)).encode()).hexdigest()
    observed=digest(source)
    if observed==recipe['parent']:return source
    if observed!=recipe['current']:
        raise ValueError('Native successor differs from exact reviewed source: '+relative)
    restored=source
    for current,parent in recipe['edits']:
        if restored.count(current)!=1:
            raise ValueError('Native successor delta is not unique: '+relative)
        restored=restored.replace(current,parent,1)
    if digest(restored)!=recipe['parent']:
        raise ValueError('Native successor complete parent differs: '+relative)
    return restored
